const listSyncEvents = `-- name: ListSyncEvents :many
SELECT id, vault_id, event_type, file_path, version, actor_id, device_id, metadata, created_at FROM sync_events
WHERE vault_id = $1 AND id > $2
  AND ($3::bool
       OR file_path = ANY($4::text[]) OR file_path LIKE ANY($5::text[])
       OR coalesce(metadata->>'old_path', '') = ANY($4::text[])
       OR coalesce(metadata->>'old_path', '') LIKE ANY($5::text[]))
ORDER BY id
LIMIT $6
`

